entity Prob_8_12b_Counter_4bit_Asynch_Clr_b_vhdl is				port (A: out bit_vector (3 downto 0); next_stage: out bit; Count_enable, Clk, Clear_b: in bit);end Prob_8_12b_Counter_4bit_Asynch_Clr_b_vhdl;architecture Structural of Prob_8_12b_Counter_4bit_Asynch_Clr_b_vhdl is  signal A0, A1, A2, A3: bit;  signal J0, K0, J1, K1, J2, K2, J3, K3: bit;  component JK_FF port  (Q: buffer bit; J, K, clock, Clear_b: in bit); end component;  component and2_gate 	port (y: out bit; xin1, xin2: in bit); end component;begin   A(3: 0) <=  A3 & A2 & A1 & A0;   K0 <= J0; K1 <= J1; K2 <= J2; K3 <= J3;  M0: JK_FF port map (A0, J0, K0, Clk, Clear_b);  M1: JK_FF port map (A1, J1, K1, Clk, Clear_b);  M2: JK_FF port map (A2, J2, K2, Clk, Clear_b);  M3: JK_FF port map (A3, J3, K3, Clk, Clear_b);  M4: and2_gate port map (J0, Count_enable, Clear_b);  M5: and2_gate port map (J1, J0, A0);  M6: and2_gate port map (J2, J1, A1);  M7: and2_gate port map (J3, J2, A2);  M8: and2_gate port map (next_stage, A3, J3);end Structural;entity JK_FF is		port (Q: buffer bit; J, K, clock, Clear_b: in bit);end JK_FF;architecture Behavioral of JK_FF is 	begin		process (clock, Clear_b) begin    		if (Clear_b = '0') then Q <= '0';    		elsif  clock'event and clock = '1' then     			case (J & K) is      				when "00" =>	Q <= Q;      				when "01" =>	Q <= '0';      				when "10" =>	Q <= '1';      				when "11" =>	Q <= not Q;				end case;
			end if;end Behavioral;entity and2_gate			port (y: out bit; xin1, xin: in bit);   end and2_gate;	architecture Behavioral of and2_gate isbegin	y <= xin1 and xin2;end Behavioral;